commands.code:
mkdir -p ~/dev-opps-lab/infra/modules/notice ~/dev-opps-lab/infra/dev18/output ~/dev-opps-lab/infra/stage18/output ~/dev-opps-lab/evidence/week-18
cd ~/dev-opps-lab/infra
cat > modules/notice/main.tf <<'EOF'
terraform {
  required_providers { local = { source = "hashicorp/local", version = "~> 2.5" } }
}
variable "environment" {
  type = string
  validation {
    condition = contains(["dev", "stage"], var.environment)
    error_message = "Choose dev or stage."
  }
}
variable "output_dir" { type = string }
variable "message" { type = string }
resource "local_file" "notice" {
  filename = "${var.output_dir}/${var.environment}.txt"
  content = "${var.message}\n"
  file_permission = "0644"
}
output "path" { value = local_file.notice.filename }
EOF
cat > dev18/main.tf <<'EOF'
terraform { required_version = ">= 1.10, < 2.0" }
variable "message" { default = "A reviewed development configuration" }
module "notice" {
  source = "../modules/notice"
  environment = "dev"
  output_dir = "${path.root}/output"
  message = var.message
}
output "path" { value = module.notice.path }
EOF
cp local17/.gitignore dev18/.gitignore
cp local17/.gitignore stage18/.gitignore
cd dev18
terraform init
terraform fmt -recursive
terraform validate
terraform plan -out=local.tfplan
terraform show -no-color local.tfplan
terraform apply local.tfplan

mkdir -p ~/dev-opps-lab/infra/free18/{dev,stage}
cd ~/dev-opps-lab/infra/free18
python3 - <<'PY'
from pathlib import Path
for env in ("dev", "stage"):
    p = Path(env) / "main.tf"
    if p.exists():
        raise SystemExit(f"{p} exists; inspect it instead of overwriting")
    p.write_text('''terraform {
  required_version = ">= 1.10, < 2.0"
  required_providers { local = { source = "hashicorp/local", version = "~> 2.5" } }
}
resource "local_file" "notice" {
  filename = "${path.module}/notice.txt"
  content = "Environment: ENV\\n"
  file_permission = "0600"
}
'''.replace("ENV", env))
PY
for environment in dev stage; do
  terraform -chdir="$environment" init || break
  terraform -chdir="$environment" validate || break
  terraform -chdir="$environment" plan -out=reviewed.tfplan || break
  terraform -chdir="$environment" show -no-color reviewed.tfplan || break
done
